VAR
    Temp_Overheat_Timer : TON;
END_VAR

// Class F insulation has a maximum continuous winding temperature limit typically around 155°C, 
// but shutting down at 140°C provides a safe margin before insulation degradation occurs.

IF Motor_Winding_Temp > 140.0 THEN
    Motor_Stop := TRUE;
ELSE
    // Allow stop to be cleared if fault is reset, handled elsewhere or tied to start conditions
    IF Fault_Reset THEN
        Motor_Stop := FALSE;
    END_IF;
END_IF;

